from itertools import product

def hamming_distance(s1, s2):
    return sum(c1 != c2 for c1, c2 in zip(s1, s2))

def generate_sphere(n, k, center_string):
    sphere = set()
    # Iterate through all 2^n possible strings
    for p in product([0, 1], repeat=n):
        target_string = "".join(map(str, p))
        if hamming_distance(center_string, target_string) == k:
            sphere.add(target_string)
    return sphere

# Test case: n=5, k=2
n = 5
k = 2
centers = list(product([0, 1], repeat=n))

# Dictionary to store encountered spheres (using frozenset for hashability)
sphere_map = {}
collisions = []

for i, center_tuple in enumerate(centers):
    center_string = "".join(map(str, center_tuple))

    # Generate the set S
    S = generate_sphere(n, k, center_string)

    # Convert to frozenset for dictionary key
    S_frozen = frozenset(S)

    if S_frozen in sphere_map:
        previous_centers = sphere_map[S_frozen]
        collisions.append((center_string, previous_centers))
    else:
        sphere_map[S_frozen] = [center_string]

print(f"Number of unique spheres found for n={n}, k={k}: {len(sphere_map)}")
if collisions:
    print("Collisions found:")
    for c1, centers in collisions:
        print(f"  Sphere generated by {c1} is the same as spheres generated by: {centers}")
else:
    print("No collisions found for n=5, k=2.")

